/// Monte Carlo configuration and two-sided chi-square bounds (`scipy.stats.chi2`).
pub mod chi2 {
    /// Independent Monte Carlo runs, each with its own seed.
    pub const RUNS: usize = 100;
    /// Predict-correct steps per run.
    pub const STEPS: usize = 50;
    /// False-failure probability of each test for a consistent filter.
    pub const ALPHA: f64 = 0.001;
    /// Steps (1-based) at which the run-averaged NEES is tested.
    pub const NEES_STEPS: [usize; 4] = [20, 30, 40, 50];
    /// Bounds of the NEES of 2 states averaged over the runs at one step: `chi2(200)/100` at `α/4` (Bonferroni).
    pub const NEES2: [f64; 2] = [
        1.3488296588080928, 2.8163601953855335,
    ];
    /// Bounds of the NEES of 4 states averaged over the runs at one step: `chi2(400)/100` at `α/4` (Bonferroni).
    pub const NEES4: [f64; 2] = [
        3.045902248244523, 5.119440452007318,
    ];
    /// Bounds of the NIS of 1 measurement(s) averaged over all runs and steps: `chi2(5000)/5000`.
    pub const NIS1: [f64; 2] = [
        0.9354969264918717, 1.0671235952381504,
    ];
    /// Bounds of the NIS of 2 measurement(s) averaged over all runs and steps: `chi2(10000)/5000`.
    pub const NIS2: [f64; 2] = [
        1.90823817149919, 2.094382431525321,
    ];
}
